// Ratio returns amount times num divided by den, rounded half away from zero to a whole minor unit. The product is computed
// with big integers, so it cannot overflow. den must not be zero.
func Ratio(amount, num, den int64) int64 {
	p := new(big.Int).Mul(big.NewInt(amount), big.NewInt(num))
	d := big.NewInt(den)
	q, r := new(big.Int).QuoRem(p, d, new(big.Int))
	// QuoRem truncates toward zero. Round away from zero when the remainder is at least half of den.
	if new(big.Int).Mul(new(big.Int).Abs(r), big.NewInt(2)).Cmp(new(big.Int).Abs(d)) >= 0 && r.Sign() != 0 {
		if p.Sign()*d.Sign() > 0 {
			q.Add(q, big.NewInt(1))
		} else {
			q.Sub(q, big.NewInt(1))
		}
	}
	return q.Int64()
}

// divRound divides and rounds half away from zero.

