// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity, and
// the change is judged by it:
//   - A trialing subscription changes at once and bills nothing.
//   - An upgrade changes at once and is billed for the rest of the current period: the unused time on the old plan is
//     credited and the remaining time on the new plan is charged.
//   - A downgrade is pending until the next renewal, which bills the new plan and quantity.
//   - A change of equal value changes at once and bills nothing.
//
// A change that applies clears any pending downgrade. Fields left nil keep the subscription's current plan or quantity.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	old, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if old.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	oldPlan, ok := s.Store.Plan(orgID, old.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	newPlan := oldPlan
	planID, quantity := old.PlanID, old.Quantity
	if in.PlanID != nil {
		newPlan, _ = s.Store.Plan(orgID, *in.PlanID)
		planID = newPlan.ID
	}
	if in.Quantity != nil {
		quantity = *in.Quantity
	}
	if quantity <= 0 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	changed := planID != old.PlanID || quantity != old.Quantity
	if changed && (oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered ||
		oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval) {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	oldValue := oldPlan.UnitAmount * int64(old.Quantity)
	newValue := newPlan.UnitAmount * int64(quantity)
	trialing := old.Status == store.Trialing
	downgrade := changed && !trialing && newValue < oldValue
	upgrade := changed && !trialing && newValue > oldValue

	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			sub.PendingPlanID, sub.PendingQuantity = &planID, &quantity
			return nil
		}
		sub.PlanID, sub.Quantity = planID, quantity
		sub.PendingPlanID, sub.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if !upgrade {
		return sub, nil
	}
	paid, err := s.invoiceUpgrade(ctx, sub, oldPlan, newPlan, oldValue, newValue)
	if err != nil {
		return sub, err
	}
	if !paid {
		sub, err = s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, err
}

// invoiceUpgrade bills an upgrade for the rest of the current period. The unused time on the old plan is credited and the
// remaining time on the new plan is charged, each prorated by the share of the period that remains. It reports false when
// the charge was declined.
func (s *Service) invoiceUpgrade(ctx context.Context, sub store.Subscription, oldPlan, newPlan store.Plan, oldValue, newValue int64) (bool, error) {
	length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
	remaining := int64(sub.CurrentPeriodEnd.Sub(s.Clock.Now()) / time.Second)
	remaining = min(max(remaining, 0), length)
	lines := []store.Line{
		{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Ratio(oldValue, remaining, length)},
		{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Ratio(newValue, remaining, length)},
	}
	return s.payInvoice(ctx, sub, newPlan.Currency, lines, nil, nil)
}

