cat >> internal/subscriptions/subscriptions_test.go <<'EOF'

// chargedCustomer creates a customer whose default payment method is pm.
func chargedCustomer(e *apitest.Env, pm string) store.Customer {
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
	return c
}

func TestUpgradeBillsTheRemainingPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := chargedCustomer(e, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	// Ten of the period's 31 days have passed, so 21 remain.
	e.Clock.Set(e.Clock.Now().AddDate(0, 0, 10))
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.Quantity != 2 || got.Status != store.Active || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("upgrade = %+v", got)
	}
	if !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("the upgrade changed the period: %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
	// Old value 4000 and new value 10000 are prorated by 21/31: -2709.68 and 6774.19.
	want := []store.Line{
		{Description: "Unused time on Team", Quantity: 1, UnitAmount: -2710},
		{Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 6774},
	}
	if inv := invs[1]; inv.Status != store.InvoicePaid || !reflect.DeepEqual(inv.Lines, want) {
		t.Fatalf("prorated invoice = %+v", inv)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 4064 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeWithoutPaymentMethodStaysOpen(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || got.PlanID != pro.ID || got.Status != store.Active {
		t.Fatalf("upgrade = %+v, %v", got, err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen || len(invs[1].Lines) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
}

func TestDeclinedUpgradeAppliesAndIsPastDue(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := chargedCustomer(e, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || got.PlanID != pro.ID || got.Status != store.PastDue {
		t.Fatalf("upgrade = %+v, %v", got, err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v", invs)
	}
	if ps := e.Store.Payments(e.Acme.ID, invs[1].ID); len(ps) != 1 || ps[0].Status != store.PaymentFailed {
		t.Fatalf("payments = %+v", ps)
	}
}

func TestDowngradeIsPendingUntilRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := chargedCustomer(e, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: pro.ID, Quantity: 2})
	e.Clock.Set(e.Clock.Now().AddDate(0, 0, 10))
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.Quantity != 2 || got.PendingPlanID == nil || *got.PendingPlanID != team.ID ||
		got.PendingQuantity == nil || *got.PendingQuantity != 2 {
		t.Fatalf("downgrade = %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a downgrade was billed: %+v", invs)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ = e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.PlanID != team.ID || got.Quantity != 2 || got.PendingPlanID != nil || got.PendingQuantity != nil || got.Status != store.Active {
		t.Fatalf("after the renewal = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Lines[0].UnitAmount != 2000 || invs[1].Lines[0].Quantity != 2 || invs[1].Status != store.InvoicePaid {
		t.Fatalf("renewal invoice = %+v", invs)
	}
}

func TestChangingBackClearsPendingDowngrade(t *testing.T) {
