1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/money"
14		"example.com/tally/internal/payments"
15		"example.com/tally/internal/store"
16	)
17	
18	// Errors.
19	var (
20		ErrPlanInactive     = errors.New("the plan is not active")
21		ErrCanceled         = errors.New("the subscription is canceled")
22		ErrIncompatiblePlan = errors.New("the plans differ in currency or interval, or one of them is metered")
23	)
24	
25	// Service runs subscriptions.
26	type Service struct {
27		Store     *store.Store
28		Payments  *payments.Service
29		Clock     clock.Clock
30		Publisher payments.Publisher // nil: no events
31	}
32	
33	// CreateInput is a new subscription.
34	type CreateInput struct {
35		CustomerID      string
36		PlanID          string
37		Quantity        int // 0 means 1
38		DiscountPercent int
39	}
40	
41	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
42	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
43	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
44	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
45		plan, ok := s.Store.Plan(orgID, in.PlanID)
46		if !ok {
47			return store.Subscription{}, store.ErrNotFound
48		}
49		if !plan.Active {
50			return store.Subscription{}, ErrPlanInactive
51		}
52		if in.Quantity == 0 {
53			in.Quantity = 1
54		}
55		now := s.Clock.Now()
56		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
57			StartedAt: now, CurrentPeriodStart: now}
58		if plan.TrialDays > 0 {
59			end := now.AddDate(0, 0, plan.TrialDays)
60			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
61		} else {
62			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
63		}
64		sub, err := s.Store.CreateSubscription(sub, now)
65		if err != nil {
66			return store.Subscription{}, err
67		}
68		s.publish(ctx, orgID, "subscription.created", sub)
69		if sub.Status == store.Active && plan.UsageType == store.Licensed {
70			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
71			if err != nil {
72				return sub, err
73			}
74			if !paid {
75				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
76					return sub, err
77				}
78			}
79		}
80		return sub, nil
81	}
82	
83	// UpdateInput changes a subscription; nil fields stay as they are.
84	type UpdateInput struct {
85		PlanID   *string
86		Quantity *int
87	}
88	
89	// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity, and
90	// the change is judged by it:
91	//   - A trialing subscription changes at once and bills nothing.
92	//   - An upgrade changes at once and is billed for the rest of the current period: the unused time on the old plan is
93	//     credited and the remaining time on the new plan is charged.
94	//   - A downgrade is pending until the next renewal, which bills the new plan and quantity.
95	//   - A change of equal value changes at once and bills nothing.
96	//
97	// A change that applies clears any pending downgrade. Fields left nil keep the subscription's current plan or quantity.
98	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
99		if in.PlanID != nil {
100			p, ok := s.Store.Plan(orgID, *in.PlanID)
101			if !ok {
102				return store.Subscription{}, store.ErrNotFound
103			}
104			if !p.Active {
105				return store.Subscription{}, ErrPlanInactive
106			}
107		}
108		old, ok := s.Store.Subscription(orgID, id)
109		if !ok {
110			return store.Subscription{}, store.ErrNotFound
111		}
112		if old.Status == store.Canceled {
113			return store.Subscription{}, ErrCanceled
114		}
115		oldPlan, ok := s.Store.Plan(orgID, old.PlanID)
116		if !ok {
117			return store.Subscription{}, store.ErrNotFound
118		}
119		newPlan := oldPlan
120		planID, quantity := old.PlanID, old.Quantity
121		if in.PlanID != nil {
122			newPlan, _ = s.Store.Plan(orgID, *in.PlanID)
123			planID = newPlan.ID
124		}
125		if in.Quantity != nil {
126			quantity = *in.Quantity
127		}
128		if quantity <= 0 {
129			return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
130		}
131		changed := planID != old.PlanID || quantity != old.Quantity
132		if changed && (oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered ||
133			oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval) {
134			return store.Subscription{}, ErrIncompatiblePlan
135		}
136		oldValue := oldPlan.UnitAmount * int64(old.Quantity)
137		newValue := newPlan.UnitAmount * int64(quantity)
138		trialing := old.Status == store.Trialing
139		downgrade := changed && !trialing && newValue < oldValue
140		upgrade := changed && !trialing && newValue > oldValue
141	
142		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
143			if sub.Status == store.Canceled {
144				return ErrCanceled
145			}
146			if downgrade {
147				sub.PendingPlanID, sub.PendingQuantity = &planID, &quantity
148				return nil
149			}
150			sub.PlanID, sub.Quantity = planID, quantity
151			sub.PendingPlanID, sub.PendingQuantity = nil, nil
152			return nil
153		})
154		if err != nil {
155			return store.Subscription{}, err
156		}
157		s.publish(ctx, orgID, "subscription.updated", sub)
158		if !upgrade {
159			return sub, nil
160		}
161		paid, err := s.invoiceUpgrade(ctx, sub, oldPlan, newPlan, oldValue, newValue)
162		if err != nil {
163			return sub, err
164		}
165		if !paid {
166			sub, err = s.setStatus(ctx, sub, store.PastDue)
167		}
168		return sub, err
169	}
170	
171	// invoiceUpgrade bills an upgrade for the rest of the current period. The unused time on the old plan is credited and the
172	// remaining time on the new plan is charged, each prorated by the share of the period that remains. It reports false when
173	// the charge was declined.
174	func (s *Service) invoiceUpgrade(ctx context.Context, sub store.Subscription, oldPlan, newPlan store.Plan, oldValue, newValue int64) (bool, error) {
175		length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
176		remaining := int64(sub.CurrentPeriodEnd.Sub(s.Clock.Now()) / time.Second)
177		remaining = min(max(remaining, 0), length)
178		lines := []store.Line{
179			{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Ratio(oldValue, remaining, length)},
180			{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Ratio(newValue, remaining, length)},
181		}
182		return s.payInvoice(ctx, sub, newPlan.Currency, lines, nil, nil)
183	}
184	
185	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
186	// subscription changes nothing.
187	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
188		now := s.Clock.Now()
189		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
190			if sub.Status == store.Canceled {
191				return nil
192			}
193			if atPeriodEnd {
194				sub.CancelAtPeriodEnd = true
195				return nil
196			}
197			sub.Status, sub.CanceledAt = store.Canceled, &now
198			return nil
199		})
200		if err != nil {
201			return store.Subscription{}, err
202		}
203		if sub.Status == store.Canceled {
204			s.publish(ctx, orgID, "subscription.canceled", sub)
205		} else {
206			s.publish(ctx, orgID, "subscription.updated", sub)
207		}
208		return sub, nil
209	}
210	
211	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
212	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
213	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
214	// due. RenewDue returns how many subscriptions it renewed or canceled.
215	func (s *Service) RenewDue(ctx context.Context) (int, error) {
216		now := s.Clock.Now()
217		n := 0
218		for _, sub := range s.Store.DueSubscriptions(now) {
219			if err := ctx.Err(); err != nil {
220				return n, err
221			}
222			if err := s.renew(ctx, sub, now); err != nil {
223				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
224			}
225			n++
226		}
227		return n, nil
228	}
229	
230	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
231		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
232		if !ok {
233			return store.ErrNotFound
234		}
235		if sub.CancelAtPeriodEnd {
236			end := sub.CurrentPeriodEnd
237			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
238				x.Status, x.CanceledAt = store.Canceled, &end
239				return nil
240			})
241			if err == nil {
242				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
243			}
244			return err
245		}
246		// A pending downgrade takes effect at this renewal, so the new period is billed on the new plan and quantity.
247		if sub.PendingPlanID != nil || sub.PendingQuantity != nil {
248			var err error
249			sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
250				if x.PendingPlanID != nil {
251					x.PlanID = *x.PendingPlanID
252				}
253				if x.PendingQuantity != nil {
254					x.Quantity = *x.PendingQuantity
255				}
256				x.PendingPlanID, x.PendingQuantity = nil, nil
257				return nil
258			})
259			if err != nil {
260				return err
261			}
262			if plan, ok = s.Store.Plan(sub.OrgID, sub.PlanID); !ok {
263				return store.ErrNotFound
264			}
265		}
266		start := now
267		end := billing.AddInterval(start, plan.Interval)
268		paid := true
269		var err error
270		switch {
271		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
272			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
273		case plan.UsageType == store.Licensed:
274			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
275		}
276		if err != nil {
277			return err
278		}
279		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
280			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
281			if paid {
282				x.Status = store.Active
283			} else {
284				x.Status = store.PastDue
285			}
286			return nil
287		})
288		if err != nil {
289			return err
290		}
291		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
292		return nil
293	}
294	
295	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
296	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
297	// payment method stays open and counts as paid here (it is paid by hand).
298	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
299		var lines []store.Line
300		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
301		switch plan.UsageType {
302		case store.Licensed:
303			if plan.UnitAmount > 0 {
304				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
305			}
306		case store.Metered:
307			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
308				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
309			}
310		}
311		ps, pe := start, end
312		return s.payInvoice(ctx, sub, plan.Currency, lines, &ps, &pe)
313	}
314	
315	// payInvoice stores an invoice of a subscription with the given lines and charges it to the customer's default payment
316	// method. It reports false when the charge was declined. start and end, when set, are the period the invoice bills.
317	func (s *Service) payInvoice(ctx context.Context, sub store.Subscription, currency money.Currency, lines []store.Line, start, end *time.Time) (bool, error) {
318		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
319			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: start, PeriodEnd: end}, s.Clock.Now())
320		if err != nil {
321			return false, err
322		}
323		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
324		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
325		var decline *payments.DeclineError
326		switch {
327		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
328			return true, nil
329		case errors.As(err, &decline):
330			return false, nil
331		default:
332			return false, err
333		}
334	}
335	
336	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
337		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
338			x.Status = st
339			return nil
340		})
341		if err == nil {
342			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
343		}
344		return sub, err
345	}
346	
347	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
348		if s.Publisher != nil {
349			_ = s.Publisher.Publish(ctx, orgID, typ, data)
350		}
351	}
