252	// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
253	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
254		if !inv.Currency.Valid() {
255			return Invoice{}, invalid("unknown currency %q", inv.Currency)
256		}
257		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
258			return Invoice{}, invalid("the discount is 0 to 100 percent")
259		}
260		for _, l := range inv.Lines {
261			if l.Quantity <= 0 {
262				return Invoice{}, invalid("a line needs a positive quantity")
263			}
264		}
265		s.mu.Lock()
266		defer s.mu.Unlock()
267		org, ok := s.orgs[inv.OrgID]
268		if !ok {
269			return Invoice{}, ErrNotFound
270		}
271		c, ok := s.customers[inv.CustomerID]
272		if !ok {
273			return Invoice{}, ErrNotFound
274		}
275		if c.OrgID != inv.OrgID {
276			return Invoice{}, ErrCustomerOrgMismatch
277		}
278		inv.ID = s.newID("in")
279		inv.TaxRateBP = org.TaxRateBP
280		inv.Status = InvoiceOpen
281		inv.CreatedAt = now.UTC()
282		inv.PaidAt, inv.VoidedAt = nil, nil
283		inv = copyInvoice(inv)
284		s.invoices[inv.ID] = inv
285		return copyInvoice(inv), nil
286	}
