func TestSubscriptionPlanChangesOverTheAPI(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	euro := e.CreatePlan(e.Acme, "Euro", "EUR", "50.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": team.ID, "quantity": 2}, &sub)

	if r := e.Do("PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": euro.ID}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "incompatible_plan" {
		t.Fatalf("change to another currency: %s", r)
	}

	// An upgrade applies at once. The customer has no payment method, so its prorated invoice stays open.
	var up store.Subscription
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": pro.ID}, &up)
	if up.PlanID != pro.ID || up.PendingPlanID != nil || up.PendingQuantity != nil || up.Status != store.Active {
		t.Fatalf("upgrade = %+v", up)
	}

	// A downgrade is pending until the next renewal.
	var down store.Subscription
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": team.ID}, &down)
	if down.PlanID != pro.ID || down.PendingPlanID == nil || *down.PendingPlanID != team.ID || down.PendingQuantity == nil || *down.PendingQuantity != 2 {
		t.Fatalf("downgrade = %+v", down)
	}
}
