package subscriptions_test

import (
	"context"
	"errors"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

// A discount outside 0 to 100 percent makes the store refuse the upgrade's invoice, which is how these tests make it fail.
func TestUpgradeWhoseInvoiceCannotBeStoredLeavesTheSubscription(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := chargedCustomer(e, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	_, _ = e.Store.UpdateSubscription(e.Acme.ID, sub.ID, func(x *store.Subscription) error { x.DiscountPercent = 150; return nil })

	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID}); !errors.Is(err, store.ErrInvalid) {
		t.Fatalf("upgrade without an invoice: err = %v, want ErrInvalid", err)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID || got.PendingPlanID != nil {
		t.Fatalf("the change applied without its invoice: %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 {
		t.Fatalf("charges = %+v, want only the first invoice", cs)
	}
}

func TestCanceledSubscriptionCannotChange(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := chargedCustomer(e, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if _, err := e.Subs.Cancel(ctx, e.Acme.ID, sub.ID, false); err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID}); !errors.Is(err, subscriptions.ErrCanceled) {
		t.Fatalf("change of a canceled subscription: err = %v, want ErrCanceled", err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %+v", invs)
	}
}

// Usage, not quantity, is billed on a metered plan, so a quantity change on it applies at once without an invoice.
func TestMeteredQuantityChangeAppliesWithoutBilling(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := chargedCustomer(e, "pm_card_visa")
	metered, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: metered.ID, Quantity: 1})
	quantity := 3
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &quantity})
	if err != nil || got.Quantity != 3 || got.PlanID != metered.ID || got.PendingQuantity != nil {
		t.Fatalf("quantity change = %+v, %v", got, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 0 {
		t.Fatalf("invoices = %+v", invs)
	}
}

