257	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
258		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
259		if !ok {
260			return store.ErrNotFound
261		}
262		if sub.CancelAtPeriodEnd {
263			end := sub.CurrentPeriodEnd
264			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
265				x.Status, x.CanceledAt = store.Canceled, &end
266				return nil
267			})
