269				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
270			}
271			return err
272		}
273		// A pending downgrade takes effect at this renewal, so the new period is billed on the new plan and quantity.
274		if sub.PendingPlanID != nil || sub.PendingQuantity != nil {
275			var err error
276			sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
277				if x.PendingPlanID != nil {
278					x.PlanID = *x.PendingPlanID
279				}
280				if x.PendingQuantity != nil {
281					x.Quantity = *x.PendingQuantity
282				}
283				x.PendingPlanID, x.PendingQuantity = nil, nil
284				return nil
285			})
286			if err != nil {
287				return err
288			}
