322	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
323	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
324	// payment method stays open and counts as paid here (it is paid by hand).
325	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
326		var lines []store.Line
327		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
328		switch plan.UsageType {
329		case store.Licensed:
330			if plan.UnitAmount > 0 {
331				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
332			}
333		case store.Metered:
334			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
335				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
336			}
337		}
338		ps, pe := start, end
339		inv, err := s.createInvoice(sub, plan.Currency, lines, &ps, &pe)
340		if err != nil {
341			return false, err
342		}
343		return s.chargeInvoice(ctx, sub, inv)
344	}
