346	// createInvoice stores an open invoice of a subscription with the given lines. start and end, when set, are the period the
347	// invoice bills.
348	func (s *Service) createInvoice(sub store.Subscription, currency money.Currency, lines []store.Line, start, end *time.Time) (store.Invoice, error) {
349		return s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
350			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: start, PeriodEnd: end}, s.Clock.Now())
351	}
