353	// chargeInvoice charges an invoice of a subscription to the customer's default payment method. It reports false when the
354	// charge was declined.
355	func (s *Service) chargeInvoice(ctx context.Context, sub store.Subscription, inv store.Invoice) (bool, error) {
356		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
357		_, _, err := s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
358		var decline *payments.DeclineError
359		switch {
360		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
361			return true, nil
362		case errors.As(err, &decline):
363			return false, nil
364		default:
365			return false, err
366		}
367	}
