370		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
371			x.Status = st
372			return nil
373		})
374		if err == nil {
375			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
376		}
377		return sub, err
378	}
379	
380	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
381		if s.Publisher != nil {
382			_ = s.Publisher.Publish(ctx, orgID, typ, data)
383		}
384	}
